export function retryAfterMs(value, nowMs) {
  if (!Number.isSafeInteger(nowMs)) throw new RangeError('Invalid clock');
  if (typeof value !== 'string') return null;
  const field = value.replace(/^[ \t]+|[ \t]+$/gu, '');
  if (/^[0-9]+$/u.test(field)) {
    const ms = Number(field) * 1000;
    return Number.isSafeInteger(ms) ? ms : null;
  }
  const fields = /^([A-Za-z]{3}), (\d{2}) ([A-Za-z]{3}) (\d{4}) (\d{2}:\d{2}:\d{2}) GMT$/u.exec(field);
  if (!fields) return null;
  const [, , day, month, year, time] = fields;
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const index = months.indexOf(month);
  if (index < 0) return null;
  const date = new Date(`${year}-${String(index + 1).padStart(2, '0')}-${day}T${time}Z`);
  if (date.toUTCString() !== field) return null;
  const delay = Math.max(0, date.getTime() - nowMs);
  return Number.isSafeInteger(delay) ? delay : null;
}

