export function retryAfterMs(value, nowMs) {
  if (!Number.isSafeInteger(nowMs)) throw new RangeError();
  if (typeof value !== 'string') return null;
  if (Number.isSafeInteger(Number(value) * 1000)) return Number(value) * 1000;
  const delay = Math.max(0, Date.parse(value) - nowMs);
  return Number.isSafeInteger(delay) ? delay : null;
}

