export function singleByteRange(header, length) {
  if (!Number.isSafeInteger(length) || length < 0) throw new RangeError('Invalid resource length');
  if (typeof header !== 'string' || !length) return null;
  const match = /^bytes=([0-9]*)-([0-9]*)$/iu.exec(header.replace(/^[ \t]+|[ \t]+$/gu, ''));
  if (!match || (!match[1] && !match[2])) return null;
  const last = BigInt(length) - 1n;
  if (!match[1]) {
    const suffix = BigInt(match[2]);
    return suffix === 0n ? null : {start: suffix > last ? 0 : Number(last + 1n - suffix), end: Number(last)};
  }
  const start = BigInt(match[1]);
  const end = match[2] ? BigInt(match[2]) : last;
  if (start > last || start > end) return null;
  return {start: Number(start), end: Number(end > last ? last : end)};
}

