export async function* readNdjson(chunks, maxLineBytes = 1024) {
  if (!Number.isSafeInteger(maxLineBytes) || maxLineBytes < 1) throw new RangeError('Invalid line limit');
  const decoder = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  let line = [];
  function decode() {
    if (line.length > maxLineBytes) throw new RangeError('Line exceeds limit');
    if (line.every(byte => byte === 32 || byte === 9)) return undefined;
    let text;
    try {
      text = decoder.decode(Uint8Array.from(line));
    } catch {
      throw new SyntaxError('Invalid UTF-8');
    }
    return JSON.parse(text);
  }
  for await (const chunk of chunks) {
    if (!(chunk instanceof Uint8Array)) throw new TypeError('Expected byte chunk');
    for (const byte of chunk) {
      if (byte === 10) {
        if (line.at(-1) === 13) line.pop();
        const value = decode();
        line = [];
        if (value !== undefined) yield value;
      } else {
        line.push(byte);
        if (line.length > maxLineBytes && (line.length !== maxLineBytes + 1 || byte !== 13)) {
          throw new RangeError('Line exceeds limit');
        }
      }
    }
  }
  const value = decode();
  if (value !== undefined) yield value;
}

